CREATE OR REPLACE FUNCTION public.cancel_customer_order(order_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE target public.orders; item public.order_items; BEGIN SELECT * INTO target FROM public.orders WHERE id = order_id FOR UPDATE; IF target.id IS NULL OR target.user_id IS DISTINCT FROM auth.uid() OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF; IF target.status <> 'pending' OR target.payment_status = 'paid' THEN RAISE EXCEPTION 'Only pending, unverified orders can be cancelled'; END IF; UPDATE public.orders SET status = 'cancelled' WHERE id = order_id; IF target.coupon_id IS NOT NULL THEN UPDATE public.customer_coupons SET used_at = NULL WHERE id = target.coupon_id; END IF; FOR item IN SELECT * FROM public.order_items WHERE order_items.order_id = target.id LOOP IF item.variation_id IS NOT NULL THEN UPDATE public.product_variations SET stock = stock + item.quantity WHERE id = item.variation_id; ELSE UPDATE public.products SET stock = stock + item.quantity WHERE id = item.product_id; END IF; END LOOP; END; $$;
REVOKE ALL ON FUNCTION public.cancel_customer_order(uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cancel_customer_order(uuid) TO authenticated;